import { writeFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { fixture, layers, readFile } from "../helpers";

describe("§13.17 path-scoped rules", () => {
  it("a repo rules/backend.md replaces the personal one", async () => {
    const ws = fixture("17-rules");
    const result = await layers(ws, "repo", ["build"]);
    expect(result.code).toBe(0);
    expect(readFile(ws, "repo/.claude/rules/backend.md")).toBe(
      [
        "---",
        "# GENERATED by agent-layerz — DO NOT EDIT. Source: shop-api:rules/backend.md. Edit the source and run `alz build`.",
        "paths:",
        "  - server/**/*.ts",
        "---",
        "",
        "REPO-BACKEND: use the service layer in server/services.",
        "",
      ].join("\n"),
    );
  });

  it("an extend rule appends a section and combines paths", async () => {
    const ws = fixture("17-rules");
    expect((await layers(ws, "repo", ["build"])).code).toBe(0);
    expect(readFile(ws, "repo/.claude/rules/testing.md")).toBe(
      [
        "---",
        "# GENERATED by agent-layerz — DO NOT EDIT. Source: personal@1.0.0:rules/testing.md + shop-api:rules/testing.md. Edit the source and run `alz build`.",
        "paths:",
        '  - "**/*.test.ts"',
        "  - e2e/**",
        "---",
        "",
        "PERSONAL-TESTING: one behaviour per test.",
        "",
        "## Repo: shop-api",
        "",
        "REPO-TESTING: e2e tests run against the dev server.",
        "",
      ].join("\n"),
    );
    const explain = await layers(ws, "repo", ["explain", "rule", "testing"]);
    expect(explain.code).toBe(0);
    expect(explain.stdout).toContain("1. personal@1.0.0:rules/testing.md — rule");
    expect(explain.stdout).toContain("2. shop-api:rules/testing.md — extend: paths +[e2e/**]");
  });

  it("a hand-written .claude/rules file is a collision", async () => {
    const ws = fixture("17-rules");
    expect((await layers(ws, "repo", ["build"])).code).toBe(0);
    writeFileSync(`${ws.root}/repo/.claude/rules/mine.md`, "hand-written\n");
    const result = await layers(ws, "repo", ["build"]);
    expect(result.code).toBe(1);
    expect(result.stderr).toContain(".claude/rules/mine.md");
  });
});
